operations.schema:
input SetAccountDetailsInput {
  address: String
  chainId: Int
  label: String
}

operations.reducer:
if (action.input.address != null) state.address = action.input.address.toLowerCase();
if (action.input.chainId != null) state.chainId = action.input.chainId;
if (action.input.label != null) state.label = action.input.label;

if (action.input.xpub == null) {
  state.bitcoinXpub = null;
} else {
  const xpub = action.input.xpub.trim();
  if (!/^(xpub|tpub|vpub|uppub|zpub|Zpub|Ypub)[1-9A-HJ-NP-Za-km-z]{20,}$/.test(xpub)) {
    throw new InvalidInputError("xpub must be an extended public key: xpub/tpub/vpub/uppub/zpub/Zpub/Ypub in base58");
  }
  state.bitcoinXpub = xpub;
}

if (action.input.events.length === 0) {
  throw new EmptyImportError("An import batch must carry at least one event");
}
const isDecimal = (value: string) => /^(0|[1-9][0-9]*)(\.[0-9]+)?$/.test(value);
const seen = new Set(state.ledger.map((e) => `${e.eventIdentifier}#${e.sequenceIndex}`));
for (const event of action.input.events) {
  if (!isDecimal(event.amount)) {
    throw new InvalidAmountError(`${event.amount} is not a decimal amount`);
  }
  const key = `${event.eventIdentifier}#${event.sequenceIndex}`;
  if (seen.has(key)) {
    throw new DuplicateEventError(
      `Event ${event.eventIdentifier}#${event.sequenceIndex} already imported`,
    );
  }
  seen.add(key);
}
for (const event of action.input.events) {
  state.ledger.push({
    id: event.id,
    eventIdentifier: event.eventIdentifier,
    sequenceIndex: event.sequenceIndex,
    timestamp: event.timestamp,
    type: event.type,
    subtype: event.subtype,
    asset: event.asset,
    amount: event.amount,
    counterparty: event.counterparty ?? null,
    counterpartyLabel: null,
    notes: event.notes ?? null,
    ignored: false,
    source: "CHAIN",
    importBatch: action.input.batchId,
  });
}

operations.schema:
input SetEventIgnoredInput {
  id: OID!
  ignored: Boolean!
}

operations.reducer:
const event = state.ledger.find((e) => e.id === action.input.id);
if (!event) throw new EventNotFoundError(`Event ${action.input.id} is not in the ledger`);
event.ignored = action.input.ignored;

operations.schema:
input SetEventNotesInput {
  id: OID!
  notes: String
}

operations.reducer:
const event = state.ledger.find((e) => e.id === action.input.id);
if (!event) throw new EventNotFoundError(`Event ${action.input.id} is not in the ledger`);
event.notes = action.input.notes ?? null;

operations.schema:
input RetypeEventInput {
  id: OID!
  type: EventType!
  subtype: EventSubtype!
}

operations.reducer:
const event = state.ledger.find((e) => e.id === action.input.id);
if (!event) throw new EventNotFoundError(`Event ${action.input.id} is not in the ledger`);
event.type = action.input.type;
event.subtype = action.input.subtype;

operations.schema:
input RecordScanProgressInput {
  lastLogsBlock: Int
  lastNativeScanBlock: Int
  lastEventTimestamp: DateTime
  ranAt: DateTime!
}

operations.reducer:
const cursor = state.cursor ?? {
  lastLogsBlock: null,
  lastNativeScanBlock: null,
  lastEventTimestamp: null,
  lastRunAt: null,
};
if (
  action.input.lastLogsBlock != null &&
  cursor.lastLogsBlock != null &&
  action.input.lastLogsBlock < cursor.lastLogsBlock
) {
  throw new CursorRegressionError(
    `lastLogsBlock would regress from ${cursor.lastLogsBlock} to ${action.input.lastLogsBlock}`,
  );
}
if (
  action.input.lastNativeScanBlock != null &&
  cursor.lastNativeScanBlock != null &&
  action.input.lastNativeScanBlock < cursor.lastNativeScanBlock
) {
  throw new CursorRegressionError(
    `lastNativeScanBlock would regress from ${cursor.lastNativeScanBlock} to ${action.input.lastNativeScanBlock}`,
  );
}
if (action.input.lastLogsBlock != null) cursor.lastLogsBlock = action.input.lastLogsBlock;
if (action.input.lastNativeScanBlock != null) cursor.lastNativeScanBlock = action.input.lastNativeScanBlock;
if (action.input.lastEventTimestamp != null) cursor.lastEventTimestamp = action.input.lastEventTimestamp;
cursor.lastRunAt = action.input.ranAt;
state.cursor = cursor;

operations.schema:
input SetBackfillStateInput {
  state: BackfillPhase!
  startBlock: Int
  nextBlock: Int
}

operations.reducer:
state.backfill = {
  state: action.input.state,
  startBlock: action.input.startBlock ?? null,
  nextBlock: action.input.nextBlock ?? null,
};

operations.schema:
input SetNativeBalanceInput {
  amount: String!
  blockNumber: Int!
  observedAt: DateTime!
}

operations.reducer:
if (
  state.nativeBalance &&
  action.input.observedAt <= state.nativeBalance.observedAt
) {
  throw new BalanceStaleError(
    `A balance observed at ${action.input.observedAt} is not newer than ${state.nativeBalance.observedAt}`,
  );
}
state.nativeBalance = {
  amount: action.input.amount,
  blockNumber: action.input.blockNumber,
  observedAt: action.input.observedAt,
};
